<script setup lang="ts">import {computed,ref} from "vue";import {Eye,RefreshCw} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Toolbar from "@/components/zs/Toolbar.vue";import SearchInput from "@/components/zs/SearchInput.vue";import SidePanel from "@/components/zs/SidePanel.vue";import ZButton from "@/components/zs/ZButton.vue";import ValidationMessage from "@/components/zs/ValidationMessage.vue";import {useAsyncData} from "@/composables/useAsyncData";import {platformRepository} from "@/services/platform/repository";import {useCompanyStore} from "@/stores/company";import {setPageMeta} from "@/lib/page-meta";import type {AuditRecord} from "@/types/platform";setPageMeta("Audit Log","Immutable company activity history with before-and-after evidence.");const company=useCompanyStore(),q=ref(''),module=ref(''),action=ref(''),from=ref(''),to=ref(''),selected=ref<AuditRecord|null>(null);const state=useAsyncData(()=>platformRepository.audit(company.activeCompanyId,{module:module.value,action:action.value,from:from.value,to:to.value}),{watch:[()=>company.activeCompanyId]});const rows=computed(()=>(state.data.value?.data??[]).filter(x=>`${x.user?.name??''} ${x.action} ${x.entity_type} ${x.entity_id}`.toLowerCase().includes(q.value.toLowerCase())));const columns:Column[]=[{key:'created_at',header:'Time'},{key:'user',header:'User'},{key:'module',header:'Module'},{key:'action',header:'Action'},{key:'entity',header:'Entity'},{key:'detail',header:''}];</script>
<template><AppShell><PageHeader title="Audit Log" description="Read-only history scoped to the active company"><template #actions><ZButton variant="outline" @click="state.refresh"><RefreshCw class="size-4"/>Apply filters</ZButton></template></PageHeader><ValidationMessage :message="state.error.value?.message"/><Panel><Toolbar><SearchInput v-model="q" placeholder="Search user, action or entity"/><input v-model="module" class="field w-40" placeholder="Module"/><input v-model="action" class="field w-40" placeholder="Action"/><input v-model="from" type="date" class="field w-36"/><input v-model="to" type="date" class="field w-36"/></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1050"><template #created_at="{row}:{row:AuditRecord}"><span class="num text-xs">{{new Date(row.created_at).toLocaleString()}}</span></template><template #user="{row}:{row:AuditRecord}">{{row.user?.name??'System'}}</template><template #module="{row}">{{row.module}}</template><template #action="{row}"><span class="font-medium text-content">{{row.action}}</span></template><template #entity="{row}:{row:AuditRecord}"><p class="text-xs text-content">{{row.entity_type.split('\\').pop()}}</p><p class="num text-2xs text-content-muted">{{row.entity_id}}</p></template><template #detail="{row}"><ZButton variant="ghost" aria-label="View audit details" @click="selected=row"><Eye class="size-4"/></ZButton></template></DataTable></Panel><SidePanel :open="!!selected" title="Audit event" :description="selected?.correlation_id??undefined" @close="selected=null"><div v-if="selected" class="space-y-5"><div><p class="label-caps">Action</p><p class="mt-1 text-sm text-content">{{selected.action}}</p><p class="mt-1 text-xs text-content-muted">{{selected.user?.name??'System'}} · {{new Date(selected.created_at).toLocaleString()}}</p></div><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-md bg-surface-sunken p-3"><p class="label-caps">Before</p><pre class="mt-2 whitespace-pre-wrap text-xs text-content-secondary">{{JSON.stringify(selected.old_values,null,2)??'No prior value'}}</pre></div><div class="rounded-md bg-surface-sunken p-3"><p class="label-caps">After</p><pre class="mt-2 whitespace-pre-wrap text-xs text-content-secondary">{{JSON.stringify(selected.new_values,null,2)??'No resulting value'}}</pre></div></div><p class="text-xs text-content-muted">Audit records are immutable and retained by the authoritative backend.</p></div></SidePanel></AppShell></template>
